import{_ as e,o as s,c as i,a2 as n}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Empaquetado y distribución","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. Estructura de carpetas de plugins","slug":"_1-estructura-de-carpetas-de-plugins","link":"#_1-estructura-de-carpetas-de-plugins","children":[]},{"level":2,"title":"2. Configuración de copia automática PostBuild","slug":"_2-configuracion-de-copia-automatica-postbuild","link":"#_2-configuracion-de-copia-automatica-postbuild","children":[]},{"level":2,"title":"3. Recursos de localización incrustados","slug":"_3-recursos-de-localizacion-incrustados","link":"#_3-recursos-de-localizacion-incrustados","children":[]},{"level":2,"title":"4. Definición de versión y metadatos","slug":"_4-definicion-de-version-y-metadatos","link":"#_4-definicion-de-version-y-metadatos","children":[]},{"level":2,"title":"5. Compilación de Release y artefactos por arquitectura","slug":"_5-compilacion-de-release-y-artefactos-por-arquitectura","link":"#_5-compilacion-de-release-y-artefactos-por-arquitectura","children":[]}],"relativePath":"es-ES/dev-guide/packaging.md","filePath":"es-ES/dev-guide/packaging.md","lastUpdated":1791112464000}'),t={name:"es-ES/dev-guide/packaging.md"};function l(o,a,r,d,c,p){return s(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="empaquetado-y-distribucion" tabindex="-1">Empaquetado y distribución <a class="header-anchor" href="#empaquetado-y-distribucion" aria-label="Permalink to &quot;Empaquetado y distribución&quot;">​</a></h1><p>Este capítulo detalla las convenciones de carpetas para los ensamblados de plugins, la inclusión de librerías dependientes, el empaquetado de recursos de traducción JSON y el flujo de despliegue automatizado.</p><h2 id="_1-estructura-de-carpetas-de-plugins" tabindex="-1">1. Estructura de carpetas de plugins <a class="header-anchor" href="#_1-estructura-de-carpetas-de-plugins" aria-label="Permalink to &quot;1. Estructura de carpetas de plugins&quot;">​</a></h2><p>Lertaro escanea recursivamente la carpeta <code>Plugins\\</code> ubicada en la raíz de la aplicación. Para evitar conflictos entre dependencias de distintos plugins, se recomienda aislar cada plugin en su propia subcarpeta:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lertaro/</span></span>
<span class="line"><span>├── Lertaro.App.exe</span></span>
<span class="line"><span>├── Lertaro.PluginSdk.dll</span></span>
<span class="line"><span>└── Plugins/</span></span>
<span class="line"><span>    └── MyCustomPlugin/</span></span>
<span class="line"><span>        ├── Lertaro.Plugins.MyCustomPlugin.dll   (Ensamblado principal)</span></span>
<span class="line"><span>        ├── ThirdParty.Managed.dll               (Dependencia administrada)</span></span>
<span class="line"><span>        └── NativeLibrary.dll                    (Dependencia nativa C/C++ — colocada EN PLANO)</span></span></code></pre></div><ul><li><strong>Resolución automática de dependencias</strong>: Al cargar la DLL principal mediante <code>Assembly.LoadFrom</code>, el entorno de .NET resuelve automáticamente las dependencias adyacentes sin interferir con otros plugins.</li><li><strong>Las dependencias nativas van junto a la DLL, no bajo <code>runtimes\\&lt;rid&gt;\\native</code></strong>: los proyectos de plugin incluidos en el repositorio fijan <code>&lt;GenerateDependencyFile&gt;false&lt;/GenerateDependencyFile&gt;</code>, así que no se genera ningún <code>.deps.json</code> y el entorno no dispone de un grafo de dependencias desde el que resolver una subcarpeta de RID. Una librería nativa tiene que poder encontrarse, por lo tanto, en el directorio base de la aplicación: cópiala en plano. También es la razón de que las dos arquitecturas se publiquen como artefactos separados y no como un instalador único: una sola copia nativa, la de una arquitectura, puede ocupar ese directorio de carga plano.</li><li><strong>Tolerancia a archivos nativos</strong>: Cuando el escaneo de ensamblados encuentra binarios nativos (p. ej. <code>e_sqlite3.dll</code>), el cargador los registra como <code>Debug</code> y sigue adelante en lugar de lanzar un <code>Error</code> falso positivo.</li></ul><h2 id="_2-configuracion-de-copia-automatica-postbuild" tabindex="-1">2. Configuración de copia automática PostBuild <a class="header-anchor" href="#_2-configuracion-de-copia-automatica-postbuild" aria-label="Permalink to &quot;2. Configuración de copia automática PostBuild&quot;">​</a></h2><p>Añade un destino <code>PostBuild</code> en el archivo <code>.csproj</code> del plugin para desplegar la salida en los directorios de depuración de Lertaro tras cada compilación exitosa. Esto es lo que hacen realmente los proyectos de plugin del repositorio — fija el destino <strong>en plano</strong> y la <strong>segunda copia para el Servicio</strong>, que es lo que deja un proveedor de alias o de traducción disponible tanto para el indexador como para la interfaz:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuild&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> AfterTargets</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PostBuildEvent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\App\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Copy</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SourceFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;$(TargetDir)$(TargetName).dll&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        DestinationFolder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;..\\..\\Service\\bin\\$(Configuration)\\net10.0-windows\\Plugins\\&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">        SkipUnchangedFiles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Target</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Copia también las dependencias administradas o nativas de terceros a esa misma carpeta con un elemento <code>&lt;Copy&gt;</code> hermano si tu plugin las necesita en el momento de la carga.</p><h2 id="_3-recursos-de-localizacion-incrustados" tabindex="-1">3. Recursos de localización incrustados <a class="header-anchor" href="#_3-recursos-de-localizacion-incrustados" aria-label="Permalink to &quot;3. Recursos de localización incrustados&quot;">​</a></h2><p>Si el plugin implementa la interfaz <a href="./sdk/ui-extensions.html"><code>ITranslationProvider</code></a>, se recomienda empaquetar los archivos JSON como <strong>Recursos incrustados</strong>:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">EmbeddedResource</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Include</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Resources\\Translations\\**\\*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ItemGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Organiza los archivos como <code>Resources/Translations/{cultura}/{tipo}.json</code>, donde <code>{tipo}</code> es el <code>typeName</code> que pasas a <code>TranslationService.LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code>. Todos los plugins de este repositorio usan el nombre fijo <strong><code>Plugin.json</code></strong> (<code>Resources/Translations/es-ES/Plugin.json</code>, <code>Resources/Translations/en-US/Plugin.json</code>, …) y pasan <code>&quot;Plugin&quot;</code>; <code>App.json</code> no es una convención de los plugins — existe solo en CoreExtensions, que además aporta las cadenas de la propia interfaz del anfitrión. Las carpetas de cultura siguen los siete idiomas de la aplicación; cuando la cultura solicitada no tiene carpeta, el gestor de traducciones recurre primero a la primera cultura admitida por el propio plugin, después a <code>en-US</code>, y solo entonces al marcador de posición <code>[key]</code>.</p><h2 id="_4-definicion-de-version-y-metadatos" tabindex="-1">4. Definición de versión y metadatos <a class="header-anchor" href="#_4-definicion-de-version-y-metadatos" aria-label="Permalink to &quot;4. Definición de versión y metadatos&quot;">​</a></h2><p>Especifica la versión y la descripción en el <code>.csproj</code>:</p><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">AssemblyVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;1.2.0.0&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">FileVersion</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  &lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;Plugin de extensión para fuentes de búsqueda y acciones contextuales.&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;/</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">PropertyGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>Esta información se presentará de forma automática en la tarjeta de <strong>Configuración → Plugins</strong>.</p><h2 id="_5-compilacion-de-release-y-artefactos-por-arquitectura" tabindex="-1">5. Compilación de Release y artefactos por arquitectura <a class="header-anchor" href="#_5-compilacion-de-release-y-artefactos-por-arquitectura" aria-label="Permalink to &quot;5. Compilación de Release y artefactos por arquitectura&quot;">​</a></h2><p>Antes de ejecutar <code>make.bat</code> desde la raíz del repositorio en Windows, instala el SDK de .NET y la <a href="https://jrsoftware.org/isdl.php#v7" target="_blank" rel="noreferrer">edición de 64 bits de Inno Setup 7</a> (el script comprueba que el compilador sea realmente 7.x). Llama a <code>:build_arch</code> dos veces: una con <code>ARCH=x64</code> (publicado sin RID, como siempre) y otra con <code>ARCH=arm64</code> (una publicación cruzada con <code>-r win-arm64 --self-contained false</code>), y genera cuatro archivos en <code>dist/</code>:</p><ul><li><code>Lertaro-Setup.exe</code> y <code>Lertaro-Portable.zip</code> (x64).</li><li><code>Lertaro-Setup-arm64.exe</code> y <code>Lertaro-Portable-arm64.zip</code> (arm64).</li></ul><p>Las dos arquitecturas se publican como artefactos separados y no como un instalador único porque el plugin BrowserData lleva una librería nativa, y su directorio de carga plano, sin <code>.deps.json</code>, solo puede alojar la copia nativa de una arquitectura (mira el comentario de cabecera del script). El instalador arm64 difiere del de x64 en <code>Installer/installer.iss</code> en <code>ArchitecturesAllowed</code> (<code>arm64</code> frente a <code>x64compatible</code>), <code>ArchitecturesInstallIn64BitMode</code>, <code>SetupArchitecture=x64</code> (solo en x64), el archivo del entorno de ejecución de .NET Desktop incluido y su URL de descarga, <code>PublishDir</code> y el nombre del archivo de salida; la carga útil de cada uno es nativa de su arquitectura. El flujo de publicación calcula las sumas de verificación y sube precisamente esos cuatro nombres, y <code>UpdateAssetSelector</code> empareja las instalaciones antiguas por nombre — cambiar el nombre de un artefacto dejaría sin actualización a los usuarios ya instalados. Mantén los nombres de los artefactos alineados con <code>make.bat</code>, <code>Installer/installer.iss</code> y la lista de recursos del flujo de publicación.</p>`,22)])])}const k=e(t,[["render",l]]);export{h as __pageData,k as default};
